const { createUser, ValidationError } = require('../users');

test('accepts numeric string age and returns a number', () => {
  assert.deepStrictEqual(createUser({ name: 'Bo', age: '42' }), { name: 'Bo', age: 42 });
  assert.strictEqual(createUser({ name: 'Bo', age: 0 }).age, 0);
  assert.strictEqual(createUser({ name: 'Bo', age: '150' }).age, 150);
});

test('rejects invalid input', () => {
  const bad = [
    undefined, null,
    {}, { age: 5 },
    { name: '', age: 5 }, { name: '   ', age: 5 }, { name: 5, age: 5 },
    { name: 'A' }, { name: 'A', age: '' }, { name: 'A', age: 'abc' },
    { name: 'A', age: 1.5 }, { name: 'A', age: '1.5' }, { name: 'A', age: -1 },
    { name: 'A', age: 151 }, { name: 'A', age: NaN }, { name: 'A', age: null },
    { name: 'A', age: [] }, { name: 'A', age: '1e2' },
  ];
  for (const input of bad) {
    assert.throws(() => createUser(input), ValidationError, JSON.stringify(input));
  }
});

